mapper.sql:
WHERE 1=1
AND e.factory_id=#{qrExceptionQueryDTO.factoryId}
AND e.exception_type=#{qrExceptionQueryDTO.exceptionType}
AND LOCATE(#{qrExceptionQueryDTO.factoryKeyword},f.factory_name)>0
AND (LOCATE(#{qrExceptionQueryDTO.keyword},CONVERT(e.exception_no USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{qrExceptionQueryDTO.keyword},CONVERT(q.qr_code_id USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{qrExceptionQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{qrExceptionQueryDTO.keyword},CONVERT(sn.sn_code USING utf8mb4) COLLATE utf8mb4_bin)>0)

mapper.select:
SELECT ,f.factory_name,s.sku_code,s.prop_name,q.qr_code_id,sn.sn_code


 AND e.exception_status=#{qrExceptionQueryDTO.status}
 ORDER BY e.created_at DESC,e.id DESC LIMIT #{qrExceptionQueryDTO.limit} OFFSET #{qrExceptionQueryDTO.offset}
